#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<char, int> m{{'A', 0}, {'B', 0}, {'C', 0}};

    for (int i = 0; i < 3; ++i) {
        string s;
        cin >> s;

        if (s[1] == '>')
            ++m[s[0]];
        else
            ++m[s[2]];
    }

    if (m['A'] == 1 && m['B'] == 1 && m['C'] == 1) {
        cout << "Impossible\n";
    } else {
        for (int wins = 0; wins < 3; ++wins) {
            for (char coin = 'A'; coin <= 'C'; ++coin) {
                if (m[coin] == wins)
                    cout << coin;
            }
        }
        cout << '\n';
    }

    return 0;
}

